ons to build a target pair","to_topic":"10_Number & Counting","to_subtopic":"Integer equations & constraints","guard":"9702cf07f3fc34cbf7c89a54fd47ddb9"},{"qid":"TS-MAT-TMUA-231","from_topic":"11_Proofs","from_subtopic":"A universal divisor and an extremal witness","to_topic":"10_Number & Counting","to_subtopic":"Integers, factors & divisibility","guard":"801b628a64f729852849d472b9a267ef"},{"qid":"TS-MAT-TMUA-232","from_topic":"11_Proofs","from_subtopic":"An irrationality proof by squaring","to_topic":"11_Proofs","to_subtopic":"Proof by contradiction","guard":"98bc0fcf470124386ece9f4889e42c47"},{"qid":"TS-MAT-TMUA-233","from_topic":"11_Proofs","from_subtopic":"A counterexample must satisfy the hypothesis","to_topic":"11_Proofs","to_subtopic":"Counterexamples & disproof","guard":"0e7c04fba0d63e974aac5f6b3926e860"},{"qid":"TS-MAT-TMUA-234","from_topic":"11_Proofs","from_subtopic":"A divisibility induction with a corrective term","to_topic":"11_Proofs","to_subtopic":"Proof strategies & mathematical arguments","guard":"1f44057faec9134c645b7e4c667bb414"},{"qid":"TS-MAT-TMUA-235","from_topic":"11_Proofs","from_subtopic":"How many tests prove a polynomial identity?","to_topic":"1_Algebra & Functions","to_subtopic":"Polynomials & factorisation","guard":"37f99fae62bff04ee0907ab2b8a1bfab"},{"qid":"TS-MAT-TMUA-236","from_topic":"11_Proofs","from_subtopic":"A nonzero hypothesis in an irrationality argument","to_topic":"8_Logic","to_subtopic":"Necessary & sufficient conditions","guard":"294fd1d46ec52c0cf32aeee6a3969ca4"},{"qid":"TS-MAT-TMUA-237","from_topic":"11_Proofs","from_subtopic":"A factorisation proves a sharp inequality","to_topic":"1_Algebra & Functions","to_subtopic":"Inequalities","guard":"56d4843d2ed4a5a978aca020265cfe32"},{"qid":"TS-MAT-TMUA-238","from_topic":"11_Proofs","from_subtopic":"Pigeonhole principle after removing powers of two","to_topic":"10_Number & Counting","to_subtopic":"Pigeonhole principle","guard":"5b4a410434e592de66b5b6b52f1afd61"},{"qid":"TS-MAT-TMUA-239","from_topic":"11_Proofs","from_subtopic":"Prime divisibility before taking square roots","to_topic":"10_Number & Counting","to_subtopic":"Integers, factors & divisibility","guard":"5bc1ce7d9ee870c4fa762e80bd1a3462"},{"qid":"TS-MAT-TMUA-240","from_topic":"11_Proofs","from_subtopic":"Equality in a sum-of-squares identity","to_topic":"11_Proofs","to_subtopic":"Direct proof & algebraic arguments","guard":"eb5d6f44957fc7af6fe1f23b0cca0ccb"},{"qid":"TS-MAT-TMUA-241","from_topic":"11_Proofs","from_subtopic":"A sharp geometric pigeonhole bound","to_topic":"10_Number & Counting","to_subtopic":"Pigeonhole principle","guard":"6cfec18a415d5d28117a3dffcad4f846"},{"qid":"TS-MAT-TMUA-242","from_topic":"11_Proofs","from_subtopic":"Induction using adjacent recurrence terms","to_topic":"2_Sequences","to_subtopic":"Summation & series","guard":"922ef9ea23def6ff0b3214b1c2e4bbc5"},{"qid":"TS-MAT-TMUA-243","from_topic":"11_Proofs","from_subtopic":"Root existence from opposite end behaviour","to_topic":"11_Proofs","to_subtopic":"Proof strategies & mathematical arguments","guard":"e8b3973410e48e005e1179ce918471a8"},{"qid":"TS-MAT-TMUA-244","from_topic":"11_Proofs","from_subtopic":"The hidden gap in an induction argument","to_topic":"11_Proofs","to_subtopic":"Errors in proofs","guard":"28f022a438f528ed1dc0648b32ac1595"},{"qid":"TS-MAT-TMUA-245","from_topic":"11_Proofs","from_subtopic":"Conjugates and parity of irrational powers","to_topic":"2_Sequences","to_subtopic":"Binomial expansion & coefficients","guard":"c14142e4ca0e3567529da151912eadce"},{"qid":"TS-MAT-TMUA-246","from_topic":"11_Proofs","from_subtopic":"An invariant plus growth proves infinitude","to_topic":"11_Proofs","to_subtopic":"Proof strategies & mathematical arguments","guard":"cfb793a7fe07f965506d6bb1fa275e83"},{"qid":"TS-MAT-TMUA-247","from_topic":"11_Proofs","from_subtopic":"A parity obstruction in a tiling","to_topic":"10_Number & Counting","to_subtopic":"Arrangements & combinatorial constraints","guard":"ed0d828c4bd3569e528734e40f67694f"},{"qid":"TS-MAT-TMUA-248","from_topic":"11_Proofs","from_subtopic":"Sorting columns preserves sorted rows","to_topic":"11_Proofs","to_subtopic":"Proof strategies & mathematical arguments","guard":"c74c23dda5f2df0fa61f5aed3d3e663a"},{"qid":"TS-MAT-TMUA-249","from_topic":"11_Proofs","from_subtopic":"An exact floor sum from complementary residues","to_topic":"10_Number & Counting","to_subtopic":"Remainders & modular arithmetic","guard":"37ae6619ac4ce59222dd0cf4ab05845c"},{"qid":"TS-MAT-TMUA-250","from_topic":"11_Proofs","from_subtopic":"A bijection between two triangle counts","to_topic":"10_Number & Counting","to_subtopic":"Counting principles","guard":"bcc5fd35802590deb17f3bdb7593a2ec"}]$tmua_taxonomy_plan$::jsonb;
  changed integer;
  questions_before text;
  excluded_before text;
  progress_before text;
begin
  if jsonb_array_length(plan) <> 2178
      or (select count(distinct p->>'qid') from jsonb_array_elements(plan) p) <> 2178
      or (select count(*) from public.tmua_qb_questions) <> 2200
      or (select count(*) from public.tmua_qb_questions where is_active) <> 2178 then
    raise exception 'Taxonomy coverage changed; review the new bank before publishing';
  end if;

  perform q.qid from public.tmua_qb_questions q
    join jsonb_to_recordset(plan) p(qid text) using(qid)
    order by q.qid for update of q;

  if exists (
    select 1 from jsonb_to_recordset(plan) p(qid text, from_topic text, from_subtopic text, to_topic text, to_subtopic text, guard text)
    left join public.tmua_qb_questions q using(qid)
    where q.qid is null or not q.is_active
      or md5((to_jsonb(q)-array['topic','subtopic'])::text) is distinct from p.guard
      or not ((q.topic is not distinct from p.from_topic and q.subtopic is not distinct from p.from_subtopic)
        or (q.topic is not distinct from p.to_topic and q.subtopic is not distinct from p.to_subtopic))
  ) then raise exception 'A question differs from the reviewed snapshot; no taxonomy changes applied'; end if;

  select md5(string_agg(q.qid||md5((to_jsonb(q)-array['topic','subtopic'])::text),'|' order by q.qid))
    into questions_before from public.tmua_qb_questions q;
  select md5(string_agg(md5(to_jsonb(q)::text),'|' order by q.qid))
    into excluded_before from public.tmua_qb_questions q where not q.is_active;
  select md5(string_agg(md5(to_jsonb(p)::text),'|' order by p.id))
    into progress_before from public.qb_progress p where p.product ilike '%tmua%';

  update public.tmua_qb_questions q set topic=p.to_topic, subtopic=p.to_subtopic
    from jsonb_to_recordset(plan) p(qid text, to_topic text, to_subtopic text)
    where q.qid=p.qid and q.is_active
      and (q.topic is distinct from p.to_topic or q.subtopic is distinct from p.to_subtopic);
  get diagnostics changed = row_count;

  if exists (
    select 1 from jsonb_to_recordset(plan) p(qid text, to_topic text, to_subtopic text)
    left join public.tmua_qb_questions q using(qid)
    where q.qid is null or not q.is_active
      or q.topic is distinct from p.to_topic or q.subtopic is distinct from p.to_subtopic
  ) then raise exception 'Taxonomy target verification failed'; end if;
  if (select md5(string_agg(q.qid||md5((to_jsonb(q)-array['topic','subtopic'])::text),'|' order by q.qid))
        from public.tmua_qb_questions q) is distinct from questions_before
    or (select md5(string_agg(md5(to_jsonb(q)::text),'|' order by q.qid))
        from public.tmua_qb_questions q where not q.is_active) is distinct from excluded_before
    or (select md5(string_agg(md5(to_jsonb(p)::text),'|' order by p.id))
        from public.qb_progress p where p.product ilike '%tmua%') is distinct from progress_before then
    raise exception 'Protected question fields, excluded questions or student progress changed';
  end if;
  raise notice 'TMUA taxonomy: % labels updated; all content, identities and progress preserved', changed;
end $tmua_taxonomy$;
commit;
select count(*)::integer as total_questions,
  count(*) filter(where is_active)::integer as active_questions,
  count(distinct topic) filter(where is_active)::integer as active_topics,
  count(distinct (topic,subtopic)) filter(where is_active)::integer as active_topic_subtopic_pairs,
  count(*) filter(where is_active and coalesce(trim(subtopic),'')='')::integer as active_without_subtopic
from public.tmua_qb_questions;
